INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
-- Ja/Nein-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Kann ein Ticketsystem im Anwendersupport dazu dienen, Anfragen zu priorisieren?', 2, '[{"text": "Ja", "correct": true, "because": "Priorisierung ist Hauptfunktion"}, {"text": "Nein", "correct": false, "because": "Ticketsysteme unterstützen das"}]'),
('00000000-0000-0000-0000-000000000000', 'Ist ein Ticketsystem im Anwendersupport nur für technische Probleme geeignet?', 2, '[{"text": "Nein", "correct": true, "because": "Auch für andere Anfragen nutzbar"}, {"text": "Ja", "correct": false, "because": "Vielseitig einsetzbar"}]'),
('00000000-0000-0000-0000-000000000000', 'Erfordert ein Ticketsystem im Anwendersupport eine Internetverbindung?', 2, '[{"text": "Ja", "correct": true, "because": "Meist webbasiert"}, {"text": "Nein", "correct": false, "because": "Online-Zugriff üblich"}]'),
('00000000-0000-0000-0000-000000000000', 'Kann ein Ticketsystem den Status einer Support-Anfrage verfolgen?', 2, '[{"text": "Ja", "correct": true, "because": "Statusverfolgung ist Kernfunktion"}, {"text": "Nein", "correct": false, "because": "Ticketsysteme bieten das"}]'),
('00000000-0000-0000-0000-000000000000', 'Ist ein Ticketsystem im Anwendersupport ohne Benutzerregistrierung nutzbar?', 2, '[{"text": "Nein", "correct": true, "because": "Registrierung für Zuordnung nötig"}, {"text": "Ja", "correct": false, "because": "Benutzeridentifikation erforderlich"}]'),

-- Single-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Welches Tool ist ein bekanntes Ticketsystem im Anwendersupport?', 2, '[{"text": "Zendesk", "correct": true, "because": "Verbreitetes Ticketsystem"}, {"text": "TeamViewer", "correct": false, "because": "Fernwartungstool"}, {"text": "Word", "correct": false, "because": "Textverarbeitung"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Funktion eines Ticketsystems ist im Anwendersupport am wichtigsten?', 3, '[{"text": "Problemzuordnung", "correct": true, "because": "Richtiger Bearbeiter entscheidend"}, {"text": "Dateianhänge", "correct": false, "because": "Zusatzfunktion"}, {"text": "Chat-Integration", "correct": false, "because": "Optional"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist der erste Schritt bei der Nutzung eines Ticketsystems im Anwendersupport?', 2, '[{"text": "Ticket erstellen", "correct": true, "because": "Startet den Prozess"}, {"text": "Ticket schließen", "correct": false, "because": "Endschritt"}, {"text": "Hardware prüfen", "correct": false, "because": "Problembezogen"}]'),
('00000000-0000-0000-0000-000000000000', 'Welcher Status in einem Ticketsystem zeigt an, dass ein Problem gelöst ist?', 2, '[{"text": "Geschlossen", "correct": true, "because": "Signalisiert Abschluss"}, {"text": "Offen", "correct": false, "because": "Noch in Bearbeitung"}, {"text": "Wartend", "correct": false, "because": "Pausiert"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Information wird in einem Ticketsystem zuerst erfasst?', 2, '[{"text": "Problembeschreibung", "correct": true, "because": "Definiert das Anliegen"}, {"text": "Lösungsschritte", "correct": false, "because": "Später hinzugefügt"}, {"text": "Bearbeitername", "correct": false, "because": "Nach Zuordnung"}]'),

-- Multiple-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Welche Funktionen bietet ein Ticketsystem im Anwendersupport?', 3, '[{"text": "Priorisierung", "correct": true, "because": "Wichtigkeit festlegen"}, {"text": "Statusverfolgung", "correct": true, "because": "Fortschritt überwachen"}, {"text": "Benutzerzuordnung", "correct": true, "because": "Verantwortung klären"}, {"text": "Bildschirmübertragung", "correct": false, "because": "Fernwartung"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile hat ein Ticketsystem im Anwendersupport?', 4, '[{"text": "Schnellere Bearbeitung", "correct": true, "because": "Effiziente Organisation"}, {"text": "Übersichtlichkeit", "correct": true, "because": "Alle Anfragen sichtbar"}, {"text": "Dokumentation", "correct": true, "because": "Nachvollziehbarkeit"}, {"text": "Hardware-Diagnose", "correct": false, "because": "Anderes Tool"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Informationen werden in einem Ticketsystem im Anwendersupport erfasst?', 3, '[{"text": "Problembeschreibung", "correct": true, "because": "Beschreibt das Anliegen"}, {"text": "Anfragedatum", "correct": true, "because": "Zeitliche Einordnung"}, {"text": "Bearbeiter", "correct": true, "because": "Verantwortlicher"}, {"text": "Internetgeschwindigkeit", "correct": false, "because": "Nicht relevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Statusoptionen gibt es typischerweise in einem Ticketsystem?', 4, '[{"text": "Offen", "correct": true, "because": "Neu eingereicht"}, {"text": "In Bearbeitung", "correct": true, "because": "Wird bearbeitet"}, {"text": "Geschlossen", "correct": true, "because": "Erledigt"}, {"text": "Gelöscht", "correct": false, "because": "Unüblich"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Arten von Anfragen kann ein Ticketsystem im Anwendersupport verwalten?', 3, '[{"text": "Technische Probleme", "correct": true, "because": "Hauptzweck"}, {"text": "Benutzerfragen", "correct": true, "because": "Supportanliegen"}, {"text": "Schulungsanfragen", "correct": true, "because": "Organisatorisch"}, {"text": "Telefonanrufe", "correct": false, "because": "Kommunikationsmittel"}]'),

-- Richtig/Falsch-Kombinationsfragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen richtig? a) Ein Ticketsystem kann Anfragen automatisch zuordnen. b) Ticketsysteme sind nur für Hardwareprobleme geeignet.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Automatisierung ja, vielseitig nutzbar"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Ein Ticketsystem verbessert die Nachverfolgbarkeit. b) Ein Ticketsystem ersetzt den direkten Support vor Ort.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Nachverfolgbarkeit ja, Ergänzung nicht Ersatz"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Ein Ticketsystem speichert die Problembeschreibung. b) Ein Ticketsystem funktioniert ohne Internetverbindung.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Speicherung ja, Internet meist nötig"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen korrekt? a) Ein Ticketsystem zeigt den Bearbeitungsstatus an. b) Ein Ticketsystem ist nur für große Unternehmen geeignet.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Status ja, auch für kleine Teams"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Ein Ticketsystem hilft bei der Dokumentation von Lösungen. b) Ein Ticketsystem kann keine Prioritäten setzen.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Dokumentation ja, Priorisierung möglich"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]');

